using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Microsoft.Win32;

namespace RtxMax {
    public sealed class Workbench {
        public Window Window;Health health;BenchResult before,after;List<ComparisonRow> comparison;Process worker;CancellationTokenSource cancel;bool busy;
        readonly string[] pages={"Overview","Benchmark","Setup","Reports"};
        public Workbench(){
            using(var text=new StringReader(Data.Resource("MainWindow.xaml")))using(var xml=System.Xml.XmlReader.Create(text))Window=(Window)XamlReader.Load(xml);
            using(var icon=new MemoryStream(Data.ResourceBytes("app.ico")))Window.Icon=BitmapFrame.Create(icon,BitmapCreateOptions.None,BitmapCacheOption.OnLoad);
            foreach(string page in pages){string selected=page;Button(page+"Nav").Click+=(s,e)=>Navigate(selected);}
            Button("ScanButton").Click+=async(s,e)=>await Scan();
            Button("AdminButton").Click+=(s,e)=>{if(Data.Admin){Info("Already elevated", "This application is already running as administrator.");return;}try{Process.Start(new ProcessStartInfo(Assembly.GetExecutingAssembly().Location){UseShellExecute=true,Verb="runas"});Window.Close();}catch(Exception error){Info("Elevation not completed",error.Message);}};
            Button("LibrariesBrowse").Click+=(s,e)=>PickFolder("LibraryPath");
            Button("BuildBrowse").Click+=(s,e)=>PickFolder("BuildPath");Button("AssetsBrowse").Click+=(s,e)=>PickFolder("AssetsPath");
            Button("ProfileBrowse").Click+=(s,e)=>{var dialog=new OpenFileDialog{Filter="Local runtime profile|*.bin|All files|*.*",Title="Select this PC's reviewed runtime profile"};if(dialog.ShowDialog(Window)==true)Box("ProfilePath").Text=dialog.FileName;};
            Button("DestinationBrowse").Click+=(s,e)=>{string selected=Folder();if(selected!=null)Box("DestinationPath").Text=Path.Combine(selected,"RTX-MAX-package-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));};
            Button("CurrentButton").Click+=async(s,e)=>await Measure("Current");Button("BeforeButton").Click+=async(s,e)=>await Measure("Before");Button("AfterButton").Click+=async(s,e)=>await Measure("After");
            Button("CancelButton").Click+=(s,e)=>{if(cancel!=null)cancel.Cancel();try{if(worker!=null&&!worker.HasExited)worker.Kill();}catch{}Log("Stop requested. An incomplete measurement is not treated as a pass.");};
            Button("CompareButton").Click+=(s,e)=>ImportComparison();
            Button("DownloadLibraries").Click+=async(s,e)=>{
                if(MessageBox.Show(Window,"Download about 541 MiB from NVIDIA's official servers into your local app-data folder? The pinned archive sizes and SHA-256 hashes will be checked. CUDA/cuBLAS licenses are retained. No display driver will be installed or changed.","Get benchmark libraries",MessageBoxButton.OKCancel,MessageBoxImage.Information)!=MessageBoxResult.OK)return;
                await Operation("Getting verified NVIDIA libraries",async()=>{string root=await Libraries.Download(message=>Window.Dispatcher.Invoke(()=>SetText("FooterStatus",message)),cancel.Token);Box("LibraryPath").Text=root;SavePreferences();Log("Official NVIDIA benchmark dependencies downloaded and verified.");});
            };
            Button("ExtractSource").Click+=async(s,e)=>await Operation("Extracting the included GPL source",async()=>{string source=await Task.Run(()=>SourcePackage.Extract());Log("Source and setup tools are ready in the local versioned source folder.");Info("Source ready",source+"\n\nRead docs/BUILD.md and docs/INSTALL.md before firmware setup.");});
            Button("GuideButton").Click+=(s,e)=>ShowGuide();Button("SetupResultsButton").Click+=(s,e)=>Navigate("Benchmark");
            Button("StageButton").Click+=async(s,e)=>{
                string build=Box("BuildPath").Text,profile=Box("ProfilePath").Text,assets=Box("AssetsPath").Text,dest=Box("DestinationPath").Text;bool reviewed=((CheckBox)Window.FindName("ReviewCheck")).IsChecked==true;
                await Operation("Validating local setup files",async()=>{if(health==null)throw new InvalidOperationException("Scan this PC first.");Health fresh=await Task.Run(()=>Scanner.Scan());string root=await Task.Run(()=>Setup.Stage(fresh,build,profile,assets,dest,reviewed));SetText("StageStatus","Prepared and verified: "+root+". No boot installation or format was performed.");Log("Local boot-file package prepared; follow the reviewed manual boot steps.");Info("Package prepared",root+"\n\nThis folder is staged only. Follow the documented spare FAT32 USB/manual U flow, then return for After and comparison. Automatic boot is a separate qualification step.");});
            };
            Button("OpenReports").Click+=(s,e)=>{Directory.CreateDirectory(Data.Home);Process.Start(new ProcessStartInfo("explorer.exe",Data.Quote(Data.Home)){UseShellExecute=true});};
            Button("ExportHealth").Click+=(s,e)=>ExportHealth();Button("ExportComparison").Click+=(s,e)=>ExportComparison();
            SetText("ReportsLocation","Local storage: %LOCALAPPDATA%\\RTX-MAX  ·  No automatic uploads");SetText("VersionLabel","v"+Data.Version+" · Windows x64");Button("AdminButton").Content=Data.Admin?"Administrator mode":"Run as administrator";
            LoadPreferences();LoadHistory();Navigate("Overview");RefreshGates();
            Window.Closing+=(s,e)=>{if(busy){if(MessageBox.Show(Window,"An operation is running. Stop it and close the application?","Operation in progress",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes){e.Cancel=true;return;}if(cancel!=null)cancel.Cancel();try{if(worker!=null&&!worker.HasExited)worker.Kill();}catch{}}};
        }
        Button Button(string name){return (Button)Window.FindName(name);}TextBox Box(string name){return (TextBox)Window.FindName(name);}void SetText(string name,string text){((TextBlock)Window.FindName(name)).Text=text;}
        static Brush Color(string hex){return (Brush)new BrushConverter().ConvertFromString(hex);}
        public void Navigate(string page){foreach(string p in pages){((FrameworkElement)Window.FindName(p+"Page")).Visibility=p==page?Visibility.Visible:Visibility.Collapsed;Button(p+"Nav").Background=Color(p==page?"#21374B":"Transparent");}SetText("PageTitle",page=="Overview"?"Your GPU, clearly understood.":page=="Benchmark"?"Evidence before assumptions.":page=="Setup"?"A measured path to setup.":"Your local evidence.");SetText("PageSubtitle",page=="Overview"?"Check the hardware. Measure the compute. Qualify before setup.":page=="Benchmark"?"Live measurements, full output checks, matched comparisons.":page=="Setup"?"Detect → baseline → qualify → prepare → boot → verify.":"Keep the record. Share only what you choose.");}
        void Log(string message){var box=Box("ActivityLog");box.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+message+Environment.NewLine);box.ScrollToEnd();}
        void Info(string title,string text){MessageBox.Show(Window,text,title,MessageBoxButton.OK,MessageBoxImage.Information);}
        string Folder(){using(var dialog=new System.Windows.Forms.FolderBrowserDialog{Description="Choose the local folder",ShowNewFolderButton=true})return dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK?dialog.SelectedPath:null;}
        void PickFolder(string field){string folder=Folder();if(folder!=null){Box(field).Text=folder;if(field=="LibraryPath")SavePreferences();}}
        async Task Operation(string label,Func<Task> body){if(busy)return;busy=true;cancel=new CancellationTokenSource();((ProgressBar)Window.FindName("BusyBar")).Visibility=Visibility.Visible;Button("CancelButton").Visibility=Visibility.Visible;Button("CancelButton").Content="Stop operation";foreach(string key in new[]{"ScanButton","CurrentButton","BeforeButton","AfterButton","DownloadLibraries","StageButton","ExtractSource","AdminButton"})Button(key).IsEnabled=false;SetText("FooterStatus",label);Log(label+"...");try{await body();SetText("FooterStatus","Completed · "+label);}catch(OperationCanceledException){SetText("FooterStatus","Cancelled · no completed result recorded");Log("Operation cancelled.");}catch(Exception error){SetText("FooterStatus","Stopped · "+error.Message);Log("Stopped: "+error.Message);Info("Action not completed",error.Message);}finally{busy=false;cancel.Dispose();cancel=null;((ProgressBar)Window.FindName("BusyBar")).Visibility=Visibility.Collapsed;Button("CancelButton").Visibility=Visibility.Collapsed;foreach(string key in new[]{"ScanButton","CurrentButton","BeforeButton","AfterButton","DownloadLibraries","StageButton","ExtractSource","AdminButton"})Button(key).IsEnabled=true;RefreshGates();}}
        void RefreshGates(){if(busy)return;bool reference=health!=null&&health.Gpus.Count==1&&health.Gpus[0].ReferenceSignature;Button("StageButton").IsEnabled=reference;Button("StageButton").ToolTip=reference?"Validate local inputs; topology review is still required.":"Scan first. Only the reference signature can prepare this firmware port.";}
        public async Task Scan(){await Operation("Reading hardware and startup state",async()=>{health=await Task.Run(()=>Scanner.Scan());Populate(health);Data.Save(Data.Unique("health"),health);Log("Health scan saved locally. "+Scanner.Eligibility(health));});}
        public void Populate(Health value){health=value;Gpu gpu=health.Gpus.FirstOrDefault();if(gpu!=null){SetText("GpuName",gpu.Name+(health.Gpus.Count>1?"  (+"+(health.Gpus.Count-1)+" more)":""));SetText("GpuIdentity","PCI "+gpu.Device+"   /   subsystem "+gpu.Subsystem+"\nDriver "+gpu.Driver+"   ·   VBIOS "+gpu.Vbios);SetText("VramValue",gpu.Vram==null?"N/A":(gpu.Vram/1024).Value.ToString("0.#",CultureInfo.InvariantCulture)+" GiB");SetText("TempValue",gpu.Temperature==null?"N/A":gpu.Temperature.Value.ToString("0",CultureInfo.InvariantCulture)+" °C");SetText("PowerValue",gpu.PowerLimit==null?"N/A":gpu.PowerLimit.Value.ToString("0",CultureInfo.InvariantCulture)+" W");SetText("UseValue",gpu.Utilization==null?"N/A":gpu.Utilization.Value.ToString("0",CultureInfo.InvariantCulture)+" %");}else SetText("GpuName","NVIDIA telemetry unavailable");SetText("DeviceBadge",health.Elevated?"ELEVATED SCAN":"STANDARD USER SCAN");SetText("EligibilityText",Scanner.Eligibility(health));SetText("SetupGate",Scanner.Eligibility(health));SetText("EligibilityDetail",health.VerifiedExistingInstallation?"The actual internal boot route and known reference artifacts agree on this PC. This health scan does not measure current compute throughput.":gpu!=null&&gpu.ReferenceSignature?"The signature matches the reference card. A different PC still needs two cold captures, ownership review, its own profile and a controlled manual hardware test.":"Diagnostics and CUDA measurements can still be useful. This firmware port does not qualify RTX 20/40/50 or other RTX 30 setups.");var rows=(StackPanel)Window.FindName("HealthRows");rows.Children.Clear();foreach(var check in health.Checks){var grid=new Grid{Margin=new Thickness(0,8,0,8)};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(100)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(180)});grid.ColumnDefinitions.Add(new ColumnDefinition());var status=new TextBlock{Text=check.State,Foreground=Color(check.State=="PASS"?"#7CE3AC":check.State=="FAIL"?"#FF9999":check.State=="WARN"||check.State=="REVIEW"||check.State=="UNSUPPORTED"?"#F5C779":"#87CFFF"),FontWeight=FontWeights.SemiBold,FontSize=12,TextWrapping=TextWrapping.Wrap};var name=new TextBlock{Text=check.Name,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,14,0)};var detail=new TextBlock{Text=check.Detail,Foreground=Color("#A8BBD0"),TextWrapping=TextWrapping.Wrap,FontSize=13};Grid.SetColumn(name,1);Grid.SetColumn(detail,2);grid.Children.Add(status);grid.Children.Add(name);grid.Children.Add(detail);rows.Children.Add(grid);}}
        async Task Measure(string stage){
            await Operation("Running "+stage+" compute measurement",async()=>{
                if(health==null){health=await Task.Run(()=>Scanner.Scan());Populate(health);}if(health.Gpus.Count!=1)throw new InvalidOperationException("The first desktop release requires exactly one NVIDIA GPU for measurements.");if(String.IsNullOrWhiteSpace(Box("LibraryPath").Text)||!Directory.Exists(Box("LibraryPath").Text))throw new DirectoryNotFoundException("Select a CUDA/cuBLAS library folder or get verified NVIDIA libraries first.");
                if(MessageBox.Show(Window,"Run a bounded GPU compute load? Output is verified, with a temperature stop at 85 °C. Close other GPU workloads. A Before label requires an observed normal Windows boot; a Current measurement makes no stock/unlocked claim.","Start "+stage+" measurement",MessageBoxButton.OKCancel,MessageBoxImage.Information)!=MessageBoxResult.OK)return;
                var request=new BenchRequest{Stage=stage,LibraryRoot=Box("LibraryPath").Text,DeviceKey=health.Gpus[0].DeviceKey};string input=Data.Unique("sessions",".request.json"),output=Data.Unique("sessions",".result.json");Data.Save(input,request);SavePreferences();
                var start=new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,"--benchmark-worker "+Data.Quote(input)+" "+Data.Quote(output)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};worker=new Process{StartInfo=start};worker.OutputDataReceived+=(s,e)=>{if(e.Data!=null)Window.Dispatcher.BeginInvoke(new Action(()=>{SetText("MeasurementStatus",e.Data);Log(e.Data);}));};worker.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)Window.Dispatcher.BeginInvoke(new Action(()=>Log(e.Data)));};worker.Start();worker.BeginOutputReadLine();worker.BeginErrorReadLine();await Task.Run(()=>worker.WaitForExit());worker.Dispose();worker=null;
                if(!File.Exists(output))throw new InvalidOperationException("Measurement stopped without a completed result. It is not treated as passed.");var result=Data.Read<BenchResult>(output);if(!result.Passed)throw new InvalidOperationException(result.Error??"Measurement did not pass.");
                if(stage=="Before")before=result;if(stage=="After")after=result;ShowMeasurement(result);Log("Measurement saved: "+Path.GetFileName(output));if(before!=null&&after!=null)UpdateComparison();
            });
        }
        void ShowMeasurement(BenchResult result){SetText("MeasurementStatus",result.Stage+" passed · independent seeded checks and every output element verified · highest sampled temperature "+result.MaxSampledTemperature.ToString("0")+" °C.");var rows=(StackPanel)Window.FindName("ComparisonRows");rows.Children.Clear();foreach(var mode in result.Measurements.Where(m=>!m.Nonconstant).GroupBy(m=>m.Mode)){double value=NativeCuda.Median(mode.Select(m=>m.Tflops));var row=new DockPanel{Margin=new Thickness(0,8,0,8)};row.Children.Add(new TextBlock{Text=mode.Key,Width=100,FontWeight=FontWeights.SemiBold});row.Children.Add(new TextBlock{Text=value.ToString("0.00",CultureInfo.InvariantCulture)+" TFLOPS",FontFamily=new FontFamily("Consolas"),Foreground=Color("#7CE3AC"),FontSize=22});rows.Children.Add(row);}SetText("ComparisonNote","Showing a real "+result.Stage+" measurement. A before/after gain is shown only after both compatible files are available.");}
        BenchResult PickResult(string title){var dialog=new OpenFileDialog{Title=title,Filter="RTX-MAX native measurement|*.json",InitialDirectory=Directory.Exists(Path.Combine(Data.Home,"sessions"))?Path.Combine(Data.Home,"sessions"):null};return dialog.ShowDialog(Window)==true?Data.Read<BenchResult>(dialog.FileName):null;}
        void ImportComparison(){try{var old=PickResult("Select the completed Before measurement");if(old==null)return;var current=PickResult("Select the completed After measurement");if(current==null)return;before=old;after=current;UpdateComparison();}catch(Exception error){Info("Comparison unavailable",error.Message);}}
        void UpdateComparison(){try{comparison=Compare.Results(before,after);var rows=(StackPanel)Window.FindName("ComparisonRows");rows.Children.Clear();double max=comparison.Max(r=>Math.Max(r.Before,r.After));foreach(var item in comparison){var grid=new Grid{Margin=new Thickness(0,10,0,10)};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(74)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(160)});grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(100)});var title=new TextBlock{Text=item.Mode,FontWeight=FontWeights.SemiBold,VerticalAlignment=VerticalAlignment.Center};var values=new TextBlock{Text=item.Before.ToString("0.00")+" → "+item.After.ToString("0.00")+"\nTFLOPS",FontFamily=new FontFamily("Consolas"),FontSize=14,VerticalAlignment=VerticalAlignment.Center};var bars=new StackPanel{VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,20,0)};bars.Children.Add(new Border{Height=7,Width=200*item.Before/max,HorizontalAlignment=HorizontalAlignment.Left,Background=Color("#7F92A9"),Margin=new Thickness(0,0,0,5)});bars.Children.Add(new Border{Height=7,Width=200*item.After/max,HorizontalAlignment=HorizontalAlignment.Left,Background=Color("#7CE3AC")});var gain=new TextBlock{Text=item.Gain.ToString("+0.0;-0.0;0.0",CultureInfo.InvariantCulture)+"%",FontFamily=new FontFamily("Consolas"),Foreground=Color(item.Gain>=0?"#7CE3AC":"#F5C779"),FontSize=22,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Right};Grid.SetColumn(values,1);Grid.SetColumn(bars,2);Grid.SetColumn(gain,3);grid.Children.Add(title);grid.Children.Add(values);grid.Children.Add(bars);grid.Children.Add(gain);rows.Children.Add(grid);}SetText("ComparisonNote","Matched device, driver/VBIOS, power limit, engine, libraries and workload. Before used normal Windows startup; After follows a newer boot. These are compute measurements, not proof of a universal unlock or game FPS gains.");Log("Matched before/after comparison passed its evidence checks.");}catch(Exception error){comparison=null;SetText("ComparisonNote","Comparison blocked: "+error.Message);Log("Comparison blocked: "+error.Message);}}
        void LoadHistory(){try{string dir=Path.Combine(Data.Home,"sessions");if(!Directory.Exists(dir))return;foreach(string file in Directory.GetFiles(dir,"*.result.json").OrderByDescending(File.GetLastWriteTimeUtc).Take(50)){var r=Data.Read<BenchResult>(file);if(!r.Passed||r.Smoke)continue;if(r.Stage=="Before"&&before==null)before=r;if(r.Stage=="After"&&after==null)after=r;}if(before!=null&&after!=null)UpdateComparison();}catch{Log("Some prior sessions could not be loaded. They have not been modified.");}}
        void LoadPreferences(){try{string file=Path.Combine(Data.Home,"preferences.json");if(File.Exists(file))Box("LibraryPath").Text=Data.Read<Dictionary<string,string>>(file)["libraries"];}catch{}if(String.IsNullOrWhiteSpace(Box("LibraryPath").Text))Box("LibraryPath").Text=Environment.GetEnvironmentVariable("CUDA_PATH")??"";}
        void SavePreferences(){Directory.CreateDirectory(Data.Home);File.WriteAllText(Path.Combine(Data.Home,"preferences.json"),Data.Json().Serialize(new Dictionary<string,string>{{"libraries",Box("LibraryPath").Text}}),new UTF8Encoding(false));}
        void ShowGuide(){try{string source=SourcePackage.Extract();var dialog=new Window{Title="RTX-MAX · full setup procedure",Owner=Window,Width=880,Height=720,Background=Color("#0D1724"),WindowStartupLocation=WindowStartupLocation.CenterOwner};var box=new TextBox{Text=File.ReadAllText(Path.Combine(source,"docs\\INSTALL.md")),IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Background=Color("#0D1724"),Foreground=Color("#EEF4FA"),FontFamily=new FontFamily("Segoe UI"),FontSize=15,Padding=new Thickness(26),BorderThickness=new Thickness(0)};dialog.Content=box;dialog.ShowDialog();}catch(Exception error){Info("Guide unavailable",error.Message);}}
        void ExportHealth(){if(health==null){Info("Scan first","Run a health scan before exporting.");return;}var dialog=new SaveFileDialog{Filter="JSON report|*.json",FileName="rtx-max-health-redacted.json"};if(dialog.ShowDialog(Window)!=true)return;var redacted=new{schema_version=1,captured_utc=health.CapturedUtc,elevated=health.Elevated,windows=health.Windows,gpus=health.Gpus.Select(g=>new{g.Name,g.Device,g.Subsystem,g.Driver,g.Vbios,g.Vram,g.Temperature,g.PowerLimit}),checks=health.Checks,verified_existing_installation=health.VerifiedExistingInstallation,performance_measured=false,partition_identifiers_omitted=true};File.WriteAllText(dialog.FileName,Data.Json().Serialize(redacted),new UTF8Encoding(false));Log("Redacted health report exported by user request.");}
        void ExportComparison(){if(comparison==null){Info("No matched comparison","Load or capture a valid Before and After pair first.");return;}var dialog=new SaveFileDialog{Filter="JSON comparison|*.json",FileName="rtx-max-comparison.json"};if(dialog.ShowDialog(Window)!=true)return;File.WriteAllText(dialog.FileName,Data.Json().Serialize(new{schema_version=1,protocol=before.Protocol,source="user_selected_native_measurements",rows=comparison,compute_gain_only=true,universal_unlock_proven=false}),new UTF8Encoding(false));Log("Matched compute comparison exported.");}
        public void Render(string directory,int width=1280,int height=840){Directory.CreateDirectory(directory);var snapshot=Scanner.Scan();foreach(string page in pages){var view=new Workbench();view.Populate(snapshot);view.RefreshGates();view.Navigate(page);var root=(FrameworkElement)view.Window.Content;view.Window.Content=null;root.Resources=view.Window.Resources;root.SetValue(Control.FontFamilyProperty,view.Window.FontFamily);root.SetValue(Control.FontSizeProperty,view.Window.FontSize);root.SetValue(Control.ForegroundProperty,view.Window.Foreground);root.Measure(new Size(width,height));root.Arrange(new Rect(0,0,width,height));root.UpdateLayout();var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(directory,page.ToLowerInvariant()+".png")))encoder.Save(file);} }
    }
    public static class Program {
        [STAThread]public static int Main(string[] args){
            try{
                if(args.Length==3&&args[0]=="--benchmark-worker")return BenchmarkWorker.Run(args[1],args[2]);
                if(args.Length==2&&args[0]=="--diagnose"){Data.Save(args[1],Scanner.Scan());return 0;}
                if(args.Length==1&&args[0]=="--extract-source"){Console.WriteLine(SourcePackage.Extract());return 0;}
                if(args.Length==3&&args[0]=="--stage-package"){var request=Data.Read<SetupRequest>(args[1]);string folder=Setup.Stage(Scanner.Scan(),request.BuildDirectory,request.ProfilePath,request.AssetsDirectory,request.Destination,request.EvidenceReviewed);Data.Save(args[2],new{passed=true,folder=folder,boot_changes_performed=false});return 0;}
                if(args.Length==1&&args[0]=="--self-test")return SelfTests.Run();
                var app=new Application{ShutdownMode=ShutdownMode.OnMainWindowClose};app.DispatcherUnhandledException+=(s,e)=>{MessageBox.Show("RTX-MAX could not complete this action: "+e.Exception.Message,"RTX-MAX",MessageBoxButton.OK,MessageBoxImage.Error);e.Handled=true;};
                var ui=new Workbench();if(args.Length==2&&args[0]=="--render-preview"){ui.Render(args[1]);return 0;}if(args.Length==2&&args[0]=="--render-preview-small"){ui.Render(args[1],1080,720);return 0;}app.Run(ui.Window);return 0;
            }catch(Exception error){string path=Data.Unique("errors",".txt");Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,error.ToString());if(args.Length==0)MessageBox.Show(error.Message+"\n\nA local error record was saved.","RTX-MAX",MessageBoxButton.OK,MessageBoxImage.Error);else Console.Error.WriteLine(error.Message);return 1;}
        }
    }
}
